  "status-notice": { type: "Component", maturity: "candidate", overview: "Inline feedback with explicit status text.", use: "Use for success, warning, error or informational feedback near affected content.", avoid: "Do not use color or icon alone to communicate a result.", anatomy: "Icon, title, description, optional action.", variants: "neutral, success, warning, destructive", sizes: "Content driven", accessibility: "Destructive defaults to alert; other tones use status. Provide a concise title or description.", api: "StatusNoticeProps adds tone, icon, title, description and action." },
  "reveal-content": { type: "Component", maturity: "candidate", overview: "Reveal supporting content when it enters view.", use: "Use sparingly to pace marketing or onboarding content.", avoid: "Do not delay essential actions or hide content behind motion.", anatomy: "One motion container; optional child sequence markers.", variants: "default, fade, group, line, section, stagger", sizes: "Content driven", accessibility: "Reduced motion and no-script users see content immediately.", api: "HTMLMotionProps plus variant, delay, distance, duration and fromOpacity. Object or callback ref receives the root div while internal viewport observation stays active." },
  collapsible: { type: "Component", maturity: "candidate", overview: "Show or hide related content while keeping its trigger in place.", use: "Use for optional details that can be disclosed in context.", avoid: "Use Dialog when attention and focus isolation are required.", anatomy: "Root, Trigger, measured Content panel and an inner visual box.", variants: "Open and closed", sizes: "Content driven", accessibility: "Base UI handles keyboard activation, aria-expanded and panel relationship.", api: "Base UI Collapsible props. Put padding, borders and opening gaps on a child inside CollapsibleContent. Keep the animated panel free of padding and external spacing so height runs from zero to its full measured size without a final jump." },
