  toast: { type: "Component", maturity: "candidate", overview: "Transient feedback after an action.", use: "Use for nonblocking results users can safely miss.", avoid: "Use StatusNotice for persistent or critical information.", anatomy: "Toaster host and toast calls.", variants: "success, info, warning, error, loading", sizes: "Sonner defaults", accessibility: "Sonner handles live announcements; keep toast text concise and include an explicit action if recovery is needed.", api: "Mount Toaster once; call toast from sonner-compatible export. Pass theme when the host app controls mode." },
