  "alert-dialog": { type: "Component", maturity: "candidate", overview: "Ask for explicit confirmation before a consequential action.", use: "Use for deletion or irreversible changes.", avoid: "Use Dialog for routine editing.", anatomy: "Trigger, Overlay, Content, Title, Description, Cancel, Action.", variants: "Destructive action and outline cancel", sizes: "Maximum width 512px", accessibility: "Radix traps focus and requires an explicit choice; provide a title and description.", api: "Radix AlertDialog props and Leement-styled action/cancel." },
  "avatar-stack": { type: "Component", maturity: "experimental", overview: "Show several collaborators in a compact group.", use: "Use beside a labeled team or member count.", avoid: "Do not rely on small photos as the only way to identify people.", anatomy: "Group of Avatar children.", variants: "Static or spacing animation", sizes: "Configurable pixel size; default 40px", accessibility: "Name the group and keep individual identity available in text or a member list.", api: "AvatarStack accepts native div props plus animate and size." },
