  "page-header": { type: "Pattern", maturity: "candidate", overview: "A consistent page title, supporting description, and nearby actions.", use: "Use at the top of a product page.", avoid: "Avoid inside a small card or repeated list item.", anatomy: "PageHeader.Content, Title, Description, Actions.", variants: "Responsive stacked and row layouts", sizes: "Content driven; actions wrap on narrow screens", accessibility: "Title is an h1. Actions remain native interactive controls.", api: "Compound PageHeader parts accept native element props." },
